<script>
 import Nav from '$lib/ui/Nav.svelte';
 let {data}=$props(); let folder=$state(null), preview=$state(null), failure=$state(''), loading=$state(false);
 const api=(path,mode='')=>'/api/file?path='+encodeURIComponent(path)+(mode?'&'+mode+'=1':'');
 async function open(path){loading=true;failure='';try{const response=await fetch(api(path));if(!response.ok)throw new Error('This file is unavailable.');const value=await response.json();if(value.directory){folder=value;preview=null;}else preview=value;}catch(error){failure=error.message;}finally{loading=false;}}
 async function publish(){failure='';try{const response=await fetch('/api/quicklook',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({path:preview.path,publish:true})});if(!response.ok)throw new Error('This file could not be published.');const value=await response.json();preview={...preview,shared:value.url};}catch(error){failure=error.message;}}
 const parent=$derived(folder?.path?.replace(/\/[^/]+\/?$/,''));
</script>
<svelte:head><title>Files · Tophat</title></svelte:head>
<main><Nav/><h1>Files</h1><nav class="roots" aria-label="Folders">{#each data.roots as root}<button onclick={()=>open(root.path)}>{root.name}</button>{/each}</nav>{#if loading}<p role="status">Opening…</p>{/if}{#if failure}<p role="alert">{failure}</p>{/if}{#if folder}<header><button onclick={()=>open(parent)}>↑ Up</button><h2>{folder.name}</h2></header><ul>{#each folder.entries as entry}<li><button onclick={()=>open(entry.path)}><span aria-hidden="true">{entry.directory?'▸':'·'}</span> {entry.name}</button></li>{/each}</ul>{:else}<p>Choose a folder to browse files on this Mac.</p>{/if}{#if preview}<section><h2>{preview.name}</h2><p><button onclick={publish}>Publish a shared preview</button>{#if preview.shared} <a href={preview.shared} target="_blank" rel="noopener">Open shared preview</a>{/if}</p><a href={api(preview.path,'raw')} target="_blank" rel="noopener">Open</a> · <a href={api(preview.path,'download')}>Download</a>{#if preview.text}<pre>{preview.text}</pre>{:else if preview.mime?.startsWith('image/')}<img src={api(preview.path,'raw')} alt={preview.name}/>{/if}</section>{/if}</main>
<style>main{max-width:960px;margin:0 auto;padding:24px;color:var(--ink)}h1{margin-top:28px}.roots{display:flex;flex-wrap:wrap;gap:8px}button{font:inherit;color:inherit;cursor:pointer;background:transparent;border:1px solid var(--line);border-radius:8px;padding:8px 12px}header{display:flex;align-items:center;gap:16px;margin-top:20px}ul{list-style:none;padding:0}li button{width:100%;text-align:left;border:0;border-radius:0;padding:12px;border-bottom:1px solid var(--line)}li button:hover{background:var(--surface)}pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:16px;border:1px solid var(--line);border-radius:8px}img{max-width:100%;display:block;margin-top:16px}section{margin-top:24px}</style>
